// Extract incoming body payload
const lead = $input.item.json.body || $input.item.json;

let isCompliant = true;
let rejectionReasons = [];

// 1. Verify Explicit Consent
if (lead.optInConsentChecked !== true && lead.optInConsentChecked !== "true") {
  isCompliant = false;
  rejectionReasons.push("REJECTED: Missing explicit SMS consent check.");
}

// 2. Validate & Sanitize US/CA Phone Number (E.164 Format)
let phone = (lead.phone || "").replace(/\D/g, ""); // Strip non-digits
if (phone.length === 10) {
  phone = "+1" + phone; // Normalize 10-digit to E.164 (+1XXXXXXXXXX)
} else if (phone.length === 11 && phone.startsWith("1")) {
  phone = "+" + phone;
} else {
  isCompliant = false;
  rejectionReasons.push("REJECTED: Invalid phone number format.");
}

// 3. Ensure A2P Mandatory STOP & Help Opt-Out Language
let messageBody = lead.messageBody || "Thanks for reaching out! A representative will contact you shortly.";
const hasStopKeyword = /stop/i.test(messageBody);

if (!hasStopKeyword) {
  messageBody += " Reply STOP to cancel.";
}

// Return structured compliance payload
return {
  json: {
    contactName: lead.fullName || "Valued Lead",
    normalizedPhone: phone,
    originalMessage: lead.messageBody,
    sanitizedMessageBody: messageBody,
    isCompliant: isCompliant,
    rejectionReasons: rejectionReasons.join(" | "),
    timestamp: new Date().toISOString()
  }
};

// Capture details from non-compliant leads
const item = $input.item.json;

return {
  json: {
    event: "A2P_COMPLIANCE_BLOCKED",
    contactName: item.contactName,
    rawPhone: item.normalizedPhone,
    rejectionReason: item.rejectionReasons,
    blockedAt: item.timestamp,
    actionTaken: "SMS_SUPPRESSED_CARRIER_PROTECTION"
  }
};
